namespace NovaHarvest.Core.Quests; public sealed class Quest { readonly List<QuestObjective> _objectives=new();public string Id{get;}public string Title{get;}public string Description{get;}public string GiverNpcId{get;}public QuestStatus Status{get;private set;}=QuestStatus.NotStarted;public QuestReward? Reward{get;private set;}public IReadOnlyList<QuestObjective> Objectives=>_objectives;public bool IsCompleted=>_objectives.Count>0&&_objectives.All(x=>x.IsCompleted);public Quest(string id,string title,string description,string giverNpcId){Id=id;Title=title;Description=description;GiverNpcId=giverNpcId;}public void AddObjective(QuestObjective o)=>_objectives.Add(o);public void SetReward(QuestReward r)=>Reward=r;public bool Start(){if(Status!=QuestStatus.NotStarted)return false;Status=QuestStatus.Active;return true;}public bool AddProgress(string id,int n){if(Status!=QuestStatus.Active)return false;var o=_objectives.FirstOrDefault(x=>x.Id==id);if(o is null)return false;o.AddProgress(n);return true;}public bool Complete(){if(Status!=QuestStatus.Active||!IsCompleted)return false;Status=QuestStatus.Completed;return true;}public void Fail(){if(Status!=QuestStatus.Completed)Status=QuestStatus.Failed;} }
